//! A portable configuration keeps independent entrances and controls. Live
//! observations are regenerated by supervision. Continuing live authority has
//! no durable substitute and refuses a complete capability export.
use super::{Conversation, Intent, InvitationAuthority};
impl Intent {
	pub fn export_configuration(&self) -> Result<Self, &'static str> {
		if !self.peering.is_empty() {
			return Err("Live publication leases cannot be exported");
		}
		if self
			.invitations
			.as_slice()
			.iter()
			.any(|row| matches!(row.authority, InvitationAuthority::Offer(_)))
		{
			return Err("Live invitation offers cannot be exported");
		}
		if self.archive_shares.as_slice().iter().any(|row| !row.durable) {
			return Err("Live archive offers cannot be exported");
		}
		if self.operations.as_slice().iter().any(|row| row.handle.role.live()) {
			return Err("Live operations custody cannot be exported");
		}
		for row in self.conversations.as_slice() {
			match row {
				Conversation::Room(room) if room.accepted.is_some() => {
					return Err(
						"A continuing live room visit cannot be exported; retain an independently supplied durable entrance first",
					);
				}
				Conversation::Direct(direct) if direct.access.is_some() || direct.introduction.is_some() => {
					return Err("Live direct access cannot be exported");
				}
				_ => {}
			}
		}
		// One admitted configuration copy owns the encoded response, bounded by
		// MAX_AUTHORITY_BYTES. No capability is restored in this metadata read.
		let mut next = self.clone();
		for row in next.directories.as_mut_slice() {
			row.name = None;
			row.inbox = None;
			row.assigned_nick = None;
		}
		for row in next.conversations.as_mut_slice() {
			match row {
				Conversation::Room(room) => {
					room.seat = None;
					room.subject = None;
					room.files = None;
					room.inbox = None;
					room.lines = Default::default();
				}
				Conversation::Direct(direct) => {
					direct.inbox = None;
					direct.lines = Default::default();
				}
			}
		}
		Ok(next)
	}
}

/// Complete portable ingress. Every selected occurrence must come from an
/// explicit recipe. Existing local custody cannot fill holes in an export.
pub struct ConfigurationImport {
	pub intent: Intent,
	pub imports: alloc::vec::Vec<ImportRecipe>,
}
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ImportRecipe {
	pub coordinate: super::custody::Coordinate,
	pub uri: alloc::string::String,
}
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct Envelope {
	#[serde(deserialize_with = "crate::fields::json_u64")]
	version: u64,
	kind: alloc::string::String,
	intent: alloc::boxed::Box<serde_json::value::RawValue>,
	#[serde(deserialize_with = "crate::fields::object_list")]
	imports: crate::fields::List<ImportRecipe, { crate::content::session::records::FIELDS_PER_PAGE }>,
}
impl ConfigurationImport {
	// One intent-sized envelope allowance covers bounded recipes and formatting.
	pub const MAX_BYTES: usize = 2 * super::custody::MAX_AUTHORITY_BYTES;
	pub fn decode(raw: &str) -> Result<Self, &'static str> {
		if raw.len() > Self::MAX_BYTES {
			return Err("Configuration exceeds its byte bound");
		}
		let envelope: Envelope = crate::fields::json_object(raw).map_err(|_| "Invalid configuration envelope")?;
		if envelope.version != 1 || envelope.kind != "rooms-configuration" {
			return Err("Unsupported configuration format");
		}
		let intent = Intent::decode(envelope.intent.get()).map_err(|_| "Invalid configuration intent")?;
		if intent.export_configuration()? != intent {
			return Err("Configuration contains derived observations");
		}
		let imports: alloc::vec::Vec<_> = envelope
			.imports
			.as_slice()
			.iter()
			.map(|entry| entry.coordinate)
			.collect();
		for (at, coordinate) in imports.iter().enumerate() {
			if coordinate.role.live() {
				return Err("Configuration contains live authority");
			}
			if imports[..at].contains(coordinate) {
				return Err("Duplicate configuration recipe");
			}
			if !intent.coordinates().any(|selected| selected == *coordinate) {
				return Err("Recipe is not selected by the configuration");
			}
		}
		if intent.coordinates().any(|selected| !imports.contains(&selected)) {
			return Err("Configuration is missing a selected capability recipe");
		}
		Ok(Self {
			intent,
			imports: envelope.imports.0,
		})
	}
}

#[cfg(test)]
mod tests {
	use super::*;
	use alloc::string::ToString;
	use core::num::NonZeroU64;
	use serde_json::json;
	fn selected() -> Intent {
		let mut intent = Intent::empty();
		intent.archive = Some(super::super::custody::FieldKey::new(
			NonZeroU64::new(1).unwrap(),
			NonZeroU64::new(2).unwrap(),
		));
		intent
	}
	fn envelope(intent: &Intent) -> serde_json::Value {
		json!({"version": 1, "kind": "rooms-configuration", "intent": intent,
			"imports": intent.coordinates().map(|coordinate| json!({"coordinate":coordinate,"uri":"ocapn://recipe"})).collect::<alloc::vec::Vec<_>>()})
	}
	#[test]
	fn configuration_requires_exact_complete_recipe_coverage() {
		let intent = selected();
		let valid = envelope(&intent);
		assert_eq!(ConfigurationImport::decode(&valid.to_string()).unwrap().intent, intent);
		let mut missing = valid.clone();
		missing["imports"] = json!([]);
		assert!(ConfigurationImport::decode(&missing.to_string()).is_err());
		let mut duplicate = valid.clone();
		duplicate["imports"]
			.as_array_mut()
			.unwrap()
			.push(valid["imports"][0].clone());
		assert!(ConfigurationImport::decode(&duplicate.to_string()).is_err());
		let mut extra = valid.clone();
		extra["intent"] = json!(Intent::empty());
		assert!(ConfigurationImport::decode(&extra.to_string()).is_err());
		let mut wrong_role = valid.clone();
		wrong_role["imports"][0]["coordinate"]["role"] = json!("archiveControl");
		assert!(ConfigurationImport::decode(&wrong_role.to_string()).is_err());
		let mut wrong_generation = valid.clone();
		wrong_generation["imports"][0]["coordinate"]["key"] = json!("00000000000000010000000000000003");
		assert!(ConfigurationImport::decode(&wrong_generation.to_string()).is_err());
		let mut unknown = valid.clone();
		unknown["custody"] = json!([]);
		assert!(ConfigurationImport::decode(&unknown.to_string()).is_err());
		let mut version = valid.clone();
		version["version"] = json!(2);
		assert!(ConfigurationImport::decode(&version.to_string()).is_err());
		let mut observed = intent.clone();
		observed.operations = crate::fields::List::new(alloc::vec![super::super::Operations {
			connection: None,
			kind: crate::session::operations::mutation::Kind::Trace,
			handle: super::super::custody::Coordinate {
				role: super::super::custody::Role::PublicationLease,
				key: super::super::custody::FieldKey::new(NonZeroU64::new(1).unwrap(), NonZeroU64::new(1).unwrap())
			},
		}])
		.unwrap();
		assert!(ConfigurationImport::decode(&envelope(&observed).to_string()).is_err());
	}
}
